-- Part 6 (diversification pass): comp_question_bank category-gap fill for civil_supervisor and
-- coating_supervisor. Audit finding: both roles previously had ONLY HSE and JUDGMENT categories
-- in this bank (5 HSE + 5 JUDGMENT rows each, satisfying the earlier gap-fill pass's bare
-- minimum but leaving TECHNICAL/GENERAL/SCENARIO completely absent — a coverage gap, not just
-- thinness). This batch adds TECHNICAL/GENERAL/SCENARIO content plus additional L4-difficulty
-- HSE/JUDGMENT items (the categories called out as thinnest in earlier passes) so a fixed-size
-- draw stops being dominated by the same handful of items. Domain grounding: ACI 318/305/306,
-- ASTM C39/C143/D1557 for civil; SSPC-SP/PA, NACE SP0169/RP0188 for coating/CP.

insert into comp_question_bank (job_role, category, sub_category, difficulty, question_text, reference_answer, key_points, excellent_answer_indicators, common_mistakes, standard_reference) values

