 jsonb_build_array('رویکرد نظام‌مند و تشخیصی به‌جای فرض فوری یک علت واحد بدون بررسی'),
 jsonb_build_array('فرض بی‌درنگ یک علت واحد (مثلاً فقط رطوبت) بدون بررسی سایر علل محتمل','تعمیر سطحی حباب‌ها بدون شناسایی و رفع علت ریشه‌ای'),
 'SSPC-PA2 / NACE (تشخیص عیوب پوشش - Blistering)'),

