 jsonb_build_array('توضیح ریسک ترک‌خوردگی و کاهش انعطاف‌پذیری پوشش در ضخامت بیش از حد', 'بررسی دیتاشیت فنی سازنده برای حداکثر ضخامت مجاز و اقدام توصیه‌شده', 'ارزیابی چسبندگی موضعی در صورت لزوم پیش از تصمیم نهایی', 'مستندسازی انحراف و اقدام اصلاحی اتخاذشده'),
